def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    bg = Counter(x for row in grid for x in row).most_common(1)[0][0]
    colors = {x for row in grid for x in row if x != bg}
    obj = max(colors, key=lambda c: sum(row.count(c) for row in grid))
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] != bg:
                continue
            if ((c > 0 and c + 1 < w and grid[r][c-1] == obj and grid[r][c+1] == obj) or
                (r > 0 and r + 1 < h and grid[r-1][c] == obj and grid[r+1][c] == obj)):
                out[r][c] = 2
    return out
